export function relevantQuestions(p: ReviewProcess, s: ScopeAnswers): ReviewQ[] {
  if (p === "te" && s["te-use"] === false) return [];
  if (SCOPE_QUESTIONS.some((q) => q.process === p && q.gate && s[q.id] === false)) return [];
  return REVIEW_QUESTIONS.filter((q) => q.process === p && (!q.when || s[q.when] === true));
}

// ── EVALUATING ANSWERS ──
export type Answer = "evidenced" | "claimed" | "informal" | "no" | "unknown" | "na";
export const ANSWER_LABEL: Record<Answer, string> = { evidenced: "Yes \u2014 evidence seen", claimed: "Yes \u2014 not yet evidenced", informal: "Informal / sometimes", no: "No", unknown: "Don't know", na: "Not applicable" };
const SCORE: Record<Answer, number | null> = { evidenced: 3, claimed: 2, informal: 1, no: 0, unknown: 0, na: null };
export type Maturity = "Strong" | "Adequate" | "Weak" | "Missing" | "Not reviewed";
const mat = (avg: number | null): Maturity => (avg === null ? "Not reviewed" : avg >= 2.6 ? "Strong" : avg >= 1.8 ? "Adequate" : avg >= 0.9 ? "Weak" : "Missing");
export interface AnswerRec { a?: Answer; note?: string }
export function evaluate(p: ReviewProcess, s: ScopeAnswers, answers: Record<string, AnswerRec>) {
  const qs = relevantQuestions(p, s); const answered = qs.filter((q) => answers[q.id]?.a);
  const areas = Array.from(new Set(qs.map((q) => q.area))).map((area) => { const list = qs.filter((q) => q.area === area); const sc = list.map((q) => SCORE[answers[q.id]?.a as Answer]).filter((x): x is number => typeof x === "number");
    // A missing or informal HIGH-risk control caps the area at Weak, whatever the average says.
    let m = mat(sc.length ? sc.reduce((a, b) => a + b, 0) / sc.length : null);
    if ((m === "Strong" || m === "Adequate") && list.some((q) => q.weight === "High" && ["no", "informal", "unknown"].includes(answers[q.id]?.a || ""))) m = "Weak";
    return { area, maturity: m, answered: list.filter((q) => answers[q.id]?.a).length, total: list.length }; });
  const sc = answered.map((q) => SCORE[answers[q.id].a as Answer]).filter((x): x is number => typeof x === "number");
  const gaps = qs.filter((q) => ["no", "informal"].includes(answers[q.id]?.a || "")).sort((a, b) => (a.weight === b.weight ? 0 : a.weight === "High" ? -1 : 1));
  const verify = qs.filter((q) => answers[q.id]?.a === "claimed"), unknown = qs.filter((q) => answers[q.id]?.a === "unknown");
  const highGap = gaps.filter((q) => q.weight === "High").length;
  let overall = mat(sc.length ? sc.reduce((a, b) => a + b, 0) / sc.length : null);
  if ((overall === "Strong" || overall === "Adequate") && (highGap > 0 || unknown.some((q) => q.weight === "High"))) overall = "Weak";
  return { questions: qs, answered: answered.length, total: qs.length, areas, overall, gaps, verify, unknown,
    headline: !answered.length ? "Not started" : answered.length < qs.length ? "In progress \u2014 " + answered.length + " of " + qs.length + " questions answered" : highGap ? highGap + " high-risk gap" + (highGap > 1 ? "s" : "") + " \u2014 the process is exposed" : gaps.length ? "Gaps to close, none high-risk" : verify.length ? "Design looks sound \u2014 now verify the evidence" : "Design looks sound and evidenced \u2014 now prove it with detection tests" };
}

