// ── IMPLEMENTATION PLAN: each gap becomes a control with owner, steps, evidence and a due window ──
export function buildPlan(p: ReviewProcess, ev: ReturnType<typeof evaluate>, risk: "High" | "Medium" | "Low") {
  const byId = (id: string) => ALL_CONTROLS.find((c) => c.id === id);
  const items = ev.gaps.map((q) => { const ctls = q.controls.map(byId).filter(Boolean) as Control[]; const c = ctls[0];
    const days = q.weight === "High" ? (risk === "Low" ? 60 : 30) : risk === "High" ? 60 : 90;
    return { question: q, control: c, controls: ctls, priority: q.weight, days,
      steps: c ? [
        "Agree the rule: write \u201c" + c.text.split(";")[0].replace(/\.$/, "") + "\u201d into the policy or procedure (owner: " + c.owner + ").",
        c.nature === "Manual" ? "Set up the checklist or template the " + c.performer + " will complete each time (" + c.freq.toLowerCase() + ")." : "Configure the system rule with IT and record the configuration (" + c.nature.toLowerCase() + " control).",
        "Run it for a full cycle and keep the evidence: " + c.evidence + ".",
        "Have it tested independently once it has operated long enough: " + c.test,
      ] : ["Define a control that answers: " + q.q, "Assign an owner and evidence", "Run and test it"] }; });
  const tests = DETECT_TESTS.filter((t) => t.process === p);
  return { items, phases: [
    { name: "Days 1\u201330", focus: "Close high-risk gaps with preventive controls (approvals, system blocks, segregation of duties) and confirm the evidence for anything claimed but not shown.", items: items.filter((i) => i.days <= 30).length },
    { name: "Days 31\u201360", focus: "Add detective controls and start running the detection tests monthly (" + tests.map((t) => t.name.toLowerCase()).slice(0, 3).join(", ") + "\u2026). Train approvers and process staff on their role cards.", items: items.filter((i) => i.days > 30 && i.days <= 60).length },
    { name: "Days 61\u201390", focus: "Test design and operating effectiveness of the new controls, classify any deficiencies, and report results to the CFO and Audit Committee.", items: items.filter((i) => i.days > 60).length },
  ] };
}
export function boardroomQuestion(entity: string, processName: string, ev: ReturnType<typeof evaluate>, unexplained: string[]): string {
  const gaps = ev.gaps.slice(0, 5).map((q) => "- " + q.q.replace(/\?$/, "") + " (answer: weak or missing)").join("\n");
  return "As our board, review the internal-control gaps found in our " + processName + " review for " + (entity || "our company") + ".\n" + (gaps || "- No design gaps recorded yet") +
    (unexplained.length ? "\nDetection tests also found unexplained exceptions: " + unexplained.join("; ") + "." : "") +
    "\nWhich gaps should we fix first, what will each fix cost in time and people, what is the risk of waiting, and who should own each fix?";
}
